#include <iostream>




#include <unordered_set>




#include <vector>




using namespace std;




int main(){int n;cin>>n;vector<long long>a;unordered_set<long long>seen;




while(n--){long long v;cin>>v;if(seen.insert(v).second)a.push_back(v);}long long x;cin>>x;




if(!seen.count(x)){cout<<"NO CHANGE\n";return 0;}




seen.erase(x);bool first=true;for(auto v:a)if(seen.count(v)){if(!first)cout<<' ';cout<<v;first=false;}




if(first)cout<<"EMPTY";cout<<'\n';}
